public class Lot {
    private final String lotNo;
    private int qty;

    public Lot(String lotNo) {
        this(lotNo, 0);          // 別のコンストラクタを呼ぶ（先頭のみ）
    }
    public Lot(String lotNo, int qty) {
        this.lotNo = lotNo;      // this でフィールドと引数を区別
        this.qty = qty;
    }
    public int getQty() { return qty; }
}

