interface Approvable {
    int MAX_LEVEL = 3;                 // public static final

    void approve(String user);         // public abstract

    default boolean canApprove(String user) {
        return !isSystem(user);
    }
    private boolean isSystem(String u) { return u.startsWith("sys"); }

    static Approvable noop() { return u -> {}; }
}

