record TestResult(String item, double value, String unit) {
    TestResult {                         // コンパクトコンストラクタ
        if (value < 0) throw new IllegalArgumentException("負の値");
        unit = unit.strip();             // 代入前の引数を加工できる
    }
    String display() { return value + " " + unit; }
}

