sealed interface Judgement permits Pass, Fail, Pending {}
record Pass(String approver) implements Judgement {}
record Fail(String reason)   implements Judgement {}
record Pending()             implements Judgement {}

// 以前の書き方
if (obj instanceof String) {
    String s = (String) obj;
    System.out.println(s.length());
}
// Java 16 以降
if (obj instanceof String s && !s.isBlank()) {
    System.out.println(s.length());
}

static String label(Judgement j) {
    return switch (j) {
        case Pass p                         -> "合格（承認: " + p.approver() + "）";
        case Fail(String reason) when reason.isBlank() -> "不合格";
        case Fail(String reason)            -> "不合格: " + reason;   // record パターン
        case Pending()                      -> "判定待ち";
    };   // sealed を網羅しているので default 不要
}
